var harry PlayerHarry;
var harry CoopCombatTarget;
var Pawn CoopRecentAttacker;

// Exact Ch1 combat only. Never changes the canonical PlayerHarry alias.
function bool IsCh1CoopCombat()
{
    local HPCoopGame G;
    G = HPCoopGame(Level.Game);
    return G != None && G.IsCh1CombatSeeker(self);
}

function bool CoopCombatMayAct()
{
    local HPCoopGame G;
    G = HPCoopGame(Level.Game);
    if (G == None || !G.IsCh1CombatSeeker(self)) return True;
    return G.IsCh1CombatOpen(self);
}

function harry GetCh1CombatTarget()
{
    if (IsCh1CoopCombat()) return CoopCombatTarget;
    return PlayerHarry;
}

function bool StopInvalidCh1Combat()
{
    // Ordinary death/disconnect abort is allowed only when story has released
    // this enemy. Never override a CutNotifyActor or capture-owned movement.
    if (!IsCh1CoopCombat() || !CoopCombatMayAct()
        || HasCoopCombatTarget(0,False)) return False;
    Velocity = vect(0,0,0);
    Acceleration = vect(0,0,0);
    ClearCoopCombatTarget();
    GotoState('patrol');
    return True;
}

function RecordCoopSpellAttacker(baseSpell Spell)
{
    local HPCoopGame G;
    local HPCoopHarry H;
    G = HPCoopGame(Level.Game);
    if (Role != ROLE_Authority || Level.NetMode == NM_Client
        || G == None || !G.IsCh1CombatOpen(self) || Spell == None
        || Spell.bDeleteMe || Spell.Role != ROLE_Authority || Spell.Level != Level)
        return;
    H = HPCoopHarry(Spell.Instigator);
    // The authoritative co-op wand sets both to the same registered caster.
    // Do not invent an attacker for scripted HandleSpell*(None) calls.
    if (H == None || Spell.Owner != H || !G.IsAIPlayerAvailable(H)) return;
    CoopRecentAttacker = H;
}

function bool AcquireCoopCombatTarget(float MaxRange, bool bUsePeripheralVision)
{
    local HPCoopGame G;
    G = HPCoopGame(Level.Game);
    if (Role != ROLE_Authority || Level.NetMode == NM_Client || G == None
        || !G.IsCh1CombatOpen(self)) return False;
    CoopCombatTarget = G.ResolveAITarget(self, CoopRecentAttacker,
        MaxRange, bUsePeripheralVision);
    // The hint is consumed by an actual attack-acquisition attempt, not by Tick
    // during stun. Do not call this before the attack's existing timer/state gate.
    CoopRecentAttacker = None;
    return CoopCombatTarget != None;
}

function bool HasCoopCombatTarget(float MaxRange, optional bool bRequireVisible)
{
    local HPCoopGame G;
    G = HPCoopGame(Level.Game);
    if (Role != ROLE_Authority || Level.NetMode == NM_Client || G == None
        || !G.IsCh1CombatOpen(self)
        || !G.IsAIPlayerAvailable(HPCoopHarry(CoopCombatTarget))) return False;
    if (MaxRange > 0 && VSize(CoopCombatTarget.Location - Location) >= MaxRange)
        return False;
    // During movement/strafe, keep one living target through temporary occlusion.
    // A shot additionally requires LOS. FOV is only an idle-acquisition check.
    return !bRequireVisible || LineOfSightTo(CoopCombatTarget);
}

function ClearCoopCombatTarget()
{
    CoopCombatTarget = None;
    CoopRecentAttacker = None;
}

