      || !HasCoopCombatTarget(fAttackRange,True)) return None;
  Shot = spellFireSmall(Spawn(Class'spellFireSmall'));
  if (Shot == None) return None;
  Shot.InitSpell(self,CoopCombatTarget);
  Shot.Instigator = self;
  // Retain HPawn.SpawnSpell's shared original difficulty adjustment. These
  // are campaign settings, never a replacement for the shot's actual target.
